class Solution:
    def sortByFrequency(self, s: str) -> str:
        left = sorted(set(s))
        out = []
        while left:
            best = left[0]
            for c in left:
                if s.count(c) > s.count(best):
                    best = c
            out.append(best * s.count(best))
            left.remove(best)
        return "".join(out)

