class Solution {
    public String sortByFrequency(String s) {
        boolean[] left = new boolean[128];
        for (char c : s.toCharArray()) left[c] = true;
        StringBuilder out = new StringBuilder();
        while (true) {
            int best = -1, bestCount = 0;
            for (int c = 0; c < 128; c++) {
                if (!left[c]) continue;
                int k = 0;
                for (int i = 0; i < s.length(); i++) if (s.charAt(i) == c) k++;
                if (k > bestCount) { best = c; bestCount = k; }
            }
            if (best < 0) break;
            for (int i = 0; i < bestCount; i++) out.append((char) best);
            left[best] = false;
        }
        return out.toString();
    }
}

