class Solution:
    def sortByFrequency(self, s: str) -> str:
        count = [0] * 128
        for ch in s:
            count[ord(ch)] += 1
        chars = [c for c in range(128) if count[c]]
        chars.sort(key=lambda c: (-count[c], c))
        return "".join(chr(c) * count[c] for c in chars)

