class Solution {
    public String sortByFrequency(String s) {
        int[] count = new int[128];
        for (char ch : s.toCharArray()) count[ch]++;
        List<Integer> chars = new ArrayList<>();
        for (int c = 0; c < 128; c++) if (count[c] > 0) chars.add(c);
        chars.sort((a, b) -> count[a] != count[b] ? count[b] - count[a] : a - b);
        StringBuilder out = new StringBuilder(s.length());
        for (int c : chars) for (int i = 0; i < count[c]; i++) out.append((char) c);
        return out.toString();
    }
}

