    for (size_t i = 0; i < n; i++) gCount[(int) s[i]]++;
    int chars[128], m = 0;
    for (int c = 0; c < 128; c++) if (gCount[c]) chars[m++] = c;
    qsort(chars, m, sizeof(int), byCountThenCode);
    char* out = malloc(n + 1);
    size_t w = 0;
    for (int k = 0; k < m; k++) for (int i = 0; i < gCount[chars[k]]; i++) out[w++] = (char) chars[k];
    out[w] = '\0';
    return out;
}

