        count = [0] * 128
        for ch in s:
            count[ord(ch)] += 1
        bucket = [[] for _ in range(len(s) + 1)]
        for c in range(128):
            if count[c]:
                bucket[count[c]].append(c)
        out = []
        for k in range(len(s), 0, -1):
            for c in bucket[k]:
                out.append(chr(c) * k)
        return "".join(out)

