class Solution {
    public String sortByFrequency(String s) {
        int n = s.length();
        int[] count = new int[128];
        for (char ch : s.toCharArray()) count[ch]++;
        List<List<Integer>> bucket = new ArrayList<>();
        for (int k = 0; k <= n; k++) bucket.add(new ArrayList<>());
        for (int c = 0; c < 128; c++) if (count[c] > 0) bucket.get(count[c]).add(c);
        StringBuilder out = new StringBuilder(n);
        for (int k = n; k >= 1; k--)
            for (int c : bucket.get(k))
                for (int i = 0; i < k; i++) out.append((char) c);
        return out.toString();
    }
}

