char* sortByFrequency(char* s) {
    int n = strlen(s);
    int count[128] = {0};
    for (int i = 0; i < n; i++) count[(int) s[i]]++;
    int* head = malloc((n + 1) * sizeof(int));
    int next[128];
    for (int k = 0; k <= n; k++) head[k] = -1;
    for (int c = 127; c >= 0; c--) {
        if (!count[c]) continue;
        next[c] = head[count[c]];
        head[count[c]] = c;
    }
    char* out = malloc(n + 1);
    int w = 0;
    for (int k = n; k >= 1; k--)
        for (int c = head[k]; c != -1; c = next[c])
            for (int i = 0; i < k; i++) out[w++] = (char) c;
    out[w] = '\0';
    free(head);
    return out;
}
